implementation:
#include <sys/epoll.h>
#include <unistd.h>
#include <sys/syscall.h>
#include <errno.h>

int epoll_ctl(int epfd, int op, int fd, struct epoll_event __user *event) {
    // Validate input parameters
    if (epfd < 0 || fd < 0 || event == NULL) {
        errno = EINVAL;
        return -1;
    }

    // Call the system call
    int result = syscall(SYS_epoll_ctl, epfd, op, fd, event);

    return result;
}
